   foreach(var v in a.GetProperty(kind).EnumerateArray()){string name=v.GetString()!,destName=(kind=="textstyles"||kind=="dimstyles"?prefix:"")+name;if(!src.Has(name))throw new ArgumentException("Missing source "+kind+": "+name);if(kind=="blocks"){var b=(BlockTableRecord)sourceTr.GetObject(src[name],OpenMode.ForRead);if(b.IsLayout||b.IsFromExternalReference)throw new ArgumentException("Cannot import layout/xref as block");}bool exists=dst.Has(destName);if(exists&&conflict=="error")throw new ArgumentException("Target name exists: "+destName);plan.Add((kind,name,destName,src[name],destTable,exists));}
  }
  if(plan.Count>100)throw new ArgumentException("At most 100 named definitions");var importedIds=new Dictionary<ObjectId,ObjectId>();
