   if(item.kind=="textstyles"){
    var sourceText=(TextStyleTableRecord)sourceTr.GetObject(item.src,OpenMode.ForRead);var record=new TextStyleTableRecord();record.Name=item.destName;record.Font=sourceText.Font;record.FileName=sourceText.FileName;record.BigFontFileName=sourceText.BigFontFileName;record.TextSize=sourceText.TextSize;record.XScale=sourceText.XScale;record.ObliquingAngle=sourceText.ObliquingAngle;record.IsVertical=sourceText.IsVertical;var table=(TextStyleTable)tr.GetObject(item.dst,OpenMode.ForWrite);newId=table.Add(record);tr.AddNewlyCreatedDBObject(record,true);
