     if(!prop.Name.StartsWith("Dim")||!prop.CanRead||!prop.CanWrite||prop.GetIndexParameters().Length!=0||prop.PropertyType==typeof(ObjectId))continue;
     prop.SetValue(record,prop.GetValue(sourceDim));
