    var table=(DimStyleTable)tr.GetObject(item.dst,OpenMode.ForWrite);newId=table.Add(record);tr.AddNewlyCreatedDBObject(record,true);
   }else {var mapping=new IdMapping();sourceDoc.Database.WblockCloneObjects(new ObjectIdCollection(new[]{item.src}),item.dst,mapping,DuplicateRecordCloning.Ignore,false);newId=mapping[item.src].Value;}
